_takeTransfer(sender, _fundAddress, feeAmount);
}
} else if (isAddLP) {
feeAmount += tAmount.mul(_addLPFee).div(10000);
if (feeAmount > 0) {
_takeTransfer(sender, _fundAddress, feeAmount);
}
} else if (_swapPairList[sender]) {
uint256 fundAmount = tAmount.mul(_buyFundFee).div(10000);
