}
return size > 0;
}

function setSwapPairList(address addr, bool enable) external onlyOwner {
require(addr != _uniswapV2Pair, "ERC20: WETH pair cannot be deleted");
require(addr != _uniswapV2UsdtPair, "ERC20: USDT pair cannot be deleted");
